-- Produtos Hidramais (Perfume de Bebê) + preço de TESTE R$ 1,00 e ativação de todos os Hidramais
-- (pedido do Daniel para testar a venda; o preço definitivo vem depois da reunião com o contador).
INSERT INTO "brands" ("id", "name", "active", "sortOrder", "createdAt", "updatedAt")
VALUES (gen_random_uuid(), 'Hidramais', true, 10, now(), now())
ON CONFLICT ("name") DO NOTHING;

-- Loção Perfume de Bebê 500ml
INSERT INTO "products" ("id", "sku", "name", "brandId", "unit", "costCents", "taxRefBps", "priceCents",
                        "stockQty", "reservedQty", "active", "createdAt", "updatedAt")
SELECT gen_random_uuid(), 'HID-BEBE-500', 'Loção Perfume de Bebê 500ml', b."id", 'UN', 0, 0, 0, 0, 0, false, now(), now()
  FROM "brands" b WHERE b."name" = 'Hidramais'
ON CONFLICT ("sku") DO NOTHING;
INSERT INTO "stored_files" ("id", "area", "fileName", "mimeType", "sizeBytes", "data", "createdAt")
SELECT gen_random_uuid(), 'products', 'hid-perfume-bebe-500.webp', 'image/webp', 22088, decode('', 'hex'), now()
WHERE NOT EXISTS (SELECT 1 FROM "stored_files" WHERE "fileName" = 'hid-perfume-bebe-500.webp');
INSERT INTO "product_images" ("id", "productId", "fileName", "mimeType", "isPrimary", "sortOrder", "createdAt")
SELECT gen_random_uuid(), p."id", 'hid-perfume-bebe-500.webp', 'image/webp', true, 0, now()
  FROM "products" p
 WHERE p."sku" = 'HID-BEBE-500' AND NOT EXISTS (SELECT 1 FROM "product_images" i WHERE i."productId" = p."id");

-- Refil Sabonete Líquido Perfume de Bebê 400ml
INSERT INTO "products" ("id", "sku", "name", "brandId", "unit", "costCents", "taxRefBps", "priceCents",
                        "stockQty", "reservedQty", "active", "createdAt", "updatedAt")
SELECT gen_random_uuid(), 'HID-BEBE-REFIL-400', 'Refil Sabonete Líquido Perfume de Bebê 400ml', b."id", 'UN', 0, 0, 0, 0, 0, false, now(), now()
  FROM "brands" b WHERE b."name" = 'Hidramais'
ON CONFLICT ("sku") DO NOTHING;
INSERT INTO "stored_files" ("id", "area", "fileName", "mimeType", "sizeBytes", "data", "createdAt")
SELECT gen_random_uuid(), 'products', 'hid-refil-sabonete-bebe-400.webp', 'image/webp', 41112, decode('', 'hex'), now()
WHERE NOT EXISTS (SELECT 1 FROM "stored_files" WHERE "fileName" = 'hid-refil-sabonete-bebe-400.webp');
INSERT INTO "product_images" ("id", "productId", "fileName", "mimeType", "isPrimary", "sortOrder", "createdAt")
SELECT gen_random_uuid(), p."id", 'hid-refil-sabonete-bebe-400.webp', 'image/webp', true, 0, now()
  FROM "products" p
 WHERE p."sku" = 'HID-BEBE-REFIL-400' AND NOT EXISTS (SELECT 1 FROM "product_images" i WHERE i."productId" = p."id");

-- Preço de teste R$ 1,00 e ativação (somente produtos Hidramais ainda sem preço)
UPDATE "products" p
   SET "priceCents" = 100, "active" = true,
       "internalNotes" = 'PREÇO DE TESTE (R$ 1,00). Definir o preço real após a reunião com o contador.',
       "updatedAt" = now()
  FROM "brands" b
 WHERE b."id" = p."brandId" AND b."name" = 'Hidramais' AND p."priceCents" = 0 AND p."deletedAt" IS NULL;
